<span class="line"><span class="line"><span style="color:#4D4D4D;font-weight:bold;">|</span><span style="color:#D4D4D4;">     </span><span style="color:#CCCCCC;">GPS</span><span style="color:#D4D4D4;">:</span><span style="color:#B48EAD;font-style:italic;">HyperionOutpost</span><span style="color:#D4D4D4;">:</span><span style="color:#B5CEA8;">227001.34</span><span style="color:#D4D4D4;">:</span><span style="color:#B5CEA8;">227004.02</span><span style="color:#D4D4D4;">:</span><span style="color:#B5CEA8;">227021.9</span><span style="color:#D4D4D4;">:</span><span style="color:#EBCB8B;">#FF75C9F1</span><span style="color:#D4D4D4;">: </span></span></span>
